/// `(page, selector, why)` — rows the port deliberately cannot reproduce.
///
/// Every entry is a *tree-shape* difference between html5ever and libxml2 (i.e.
/// `browser-dom`'s parser, not this crate's matcher) or a documented
/// selector-vocabulary superset. None of them is a CSS matching bug. The test
/// asserts each one *still* diverges, so the table cannot rot into a skip-list.
/// `(selector, why)` — selectors the port accepts and cssselect rejects, on
/// **every** page.
///
/// All seven are places where `cssselect` (a CSS3-era parser) is narrower than
/// the CSS Selectors 4 grammar Servo implements. None of them can change what
/// a *working* Python selector means: every one of these raises
/// `SelectorSyntaxError`/`ExpressionError` in the reference implementation, so
/// no the reference implementation script can be relying on the old behaviour.
/// `ARCHITECTURE.md` §1.3 signs this class off ("a handful of cssselect quirks
/// are gone") and names `*:nth-of-type()` explicitly.
const EXPECTED_DIVERGENT_SELECTORS: &[(&str, &str)] = &[
    ("li:has(a[href])", "cssselect's :has() takes a *simple selector sequence*: `:has(a)` and `:has(> p)` work, `:has(a[href])` is a syntax error"),
    ("p:not(a, b)", "cssselect's :not() takes one compound; the CSS4 selector *list* is a syntax error"),
    (".dot:first-of-type", "cssselect: `*:first-of-type is not implemented` unless an explicit type selector precedes it — ARCHITECTURE.md §1.3 signs this superset off"),
    (":nth-of-type(1)", "ditto for `*:nth-of-type()`, the case ARCHITECTURE.md §1.3 names"),
    ("div:has(p span)", "…and a descendant sequence inside :has() is a syntax error there too"),
    ("p:not(a b)", "…and so is a CSS4 complex selector inside :not()"),
    ("li:nth-child(2 of .x)", "`of S` is CSS Selectors 4; cssselect stops at the argument"),
];

