// ---------------------------------------------------------------------------
// result records
// ---------------------------------------------------------------------------

/// A comparable rendering of one result entry.
#[derive(Debug, PartialEq, Eq, Clone)]
enum Entry {
    Element {
        tag: String,
        attrs: Vec<(String, String)>,
        text: String,
        path: String,
    },
    Text {
        role: &'static str,
        value: String,
        owner_tag: String,
    },
    Attr {
        name: String,
        value: String,
        owner_tag: String,
    },
}

impl Entry {
    /// The identity key, free of tree-position information.
    fn key(&self) -> String {
        match self {
            Self::Element {
                tag, attrs, text, ..
            } => {
                let attrs = attrs
                    .iter()
                    .map(|(k, v)| format!("{k}={v:?}"))
                    .collect::<Vec<_>>()
                    .join(" ");
                format!("element <{tag} {attrs}> {text:?}")
            }
            Self::Text {
                role,
                value,
                owner_tag,
            } => {
                format!("{role} of <{owner_tag}> {value:?}")
            }
            Self::Attr {
                name,
                value,
                owner_tag,
            } => {
                format!("attr {name} of <{owner_tag}> {value:?}")
            }
        }
    }

    fn path(&self) -> Option<&str> {
        match self {
            Self::Element { path, .. } => Some(path),
            _ => None,
        }
    }

    /// Whitespace-only text results are dropped on both sides: `browser-dom`
    /// deviation #3 makes `remove_blank_text` stricter than libxml2's
    /// `areBlanks()`, so the two trees disagree about which ignorable
    /// whitespace text nodes survive. the reference implementation's own `get_all_text()` filters
    /// them too.
    fn is_blank_text(&self) -> bool {
        matches!(self, Self::Text { value, .. } if value.trim().is_empty())
    }
}

/// All whitespace removed — the identity key must survive the two parsers'
/// different ideas of which whitespace-only text nodes are ignorable.
fn squash(text: &str) -> String {
    text.split_whitespace().collect::<Vec<_>>().concat()
}

/// HTML attributes whose mere presence is the value.
///
/// libxml2's HTML parser expands a minimised boolean attribute to
/// `checked="checked"`; html5ever leaves it `checked=""`. Neither spelling is
/// wrong and neither is this crate's doing, so the *identity* key folds them
/// together — while the corpus selectors `[checked="checked"]` and
/// `[checked=""]` pin the one place where the difference is observable through
/// CSS, as declared divergences.
const BOOLEAN_ATTRS: &[&str] = &[
    "allowfullscreen",
    "async",
    "autofocus",
    "autoplay",
    "checked",
    "compact",
    "controls",
    "declare",
    "default",
    "defer",
    "disabled",
    "formnovalidate",
    "hidden",
    "ismap",
    "itemscope",
    "loop",
    "multiple",
    "muted",
    "nohref",
    "nomodule",
    "noresize",
    "noshade",
    "novalidate",
    "nowrap",
    "open",
    "playsinline",
    "readonly",
    "required",
    "reversed",
    "scoped",
    "seamless",
    "selected",
    "truespeed",
    "typemustmatch",
];

/// Fold the two trees' spellings of the *same* node onto one key.
///
/// Three normalisations, none of which can mask a CSS matching error because
/// every one of them is applied identically to both sides:
///
/// 1. Element and attribute **names are ASCII-lower-cased**. libxml2's HTML
///    parser lower-cases every name it sees (`viewBox` -> `viewbox`,
///    `linearGradient` -> `lineargradient`); html5ever applies the HTML5
///    foreign-content adjustments and keeps the camel case. cssselect
///    lower-cases the *selector* side too, so both engines still agree on what
///    matches — they just render the node differently.
/// 2. A leading `:` is stripped from an attribute name — html5ever records
///    `xmlns` in the xmlns namespace with no prefix, which `browser-dom`'s
///    `qualname::to_string` renders as `:xmlns`.
/// 3. Minimised boolean attribute values are emptied (see [`BOOLEAN_ATTRS`]).
fn normalise_attr(name: &str, value: &str) -> (String, String) {
    let name = name.trim_start_matches(':').to_ascii_lowercase();
    let value = if BOOLEAN_ATTRS.contains(&name.as_str()) && value.eq_ignore_ascii_case(&name) {
        String::new()
    } else {
        value.to_owned()
    };
    (name, value)
}

/// `lxml.etree.ElementTree.getpath()`: `/html/body/div[2]/span`, with the
/// `[n]` suffix omitted when the element is the only one of its name among its
/// siblings.
fn getpath(node: NodeRef<'_>) -> String {
    let mut segments: Vec<String> = Vec::new();
    let mut current = Some(node);
    while let Some(el) = current {
        if !el.is_element() {
            break;
        }
        let tag = el.tag();
        let siblings = el.parent().map_or(1, |p| {
            p.element_children().filter(|s| s.tag() == tag).count()
        });
        if siblings > 1 {
            segments.push(format!("{tag}[{}]", el.nth_of_type()));
        } else {
            segments.push(tag.to_owned());
        }
        current = el.parent_element();
    }
    segments.reverse();
    format!("/{}", segments.join("/"))
}

fn from_match(m: &Match<'_>) -> Entry {
    match m.value() {
        MatchValue::Element => {
            let el = m.element();
            let mut attrs: Vec<(String, String)> = el
                .attrs()
                .iter_qual()
                .map(|(name, value)| {
                    normalise_attr(&browser_dom::qualname::to_string(name), value)
                })
                .collect();
            attrs.sort();
            Entry::Element {
                tag: el.tag().to_ascii_lowercase(),
                attrs,
                text: squash(&el.text_content()),
                path: getpath(el),
            }
        }
        MatchValue::Text { node, role } => Entry::Text {
            role: match role {
                TextRole::Text => "text",
                TextRole::Tail => "tail",
            },
            value: node.as_text().unwrap_or_default().to_owned(),
            owner_tag: m.element().tag().to_ascii_lowercase(),
        },
        MatchValue::Attr { name, value } => Entry::Attr {
            name: name.to_string(),
            value: (*value).to_owned(),
            owner_tag: m.element().tag().to_ascii_lowercase(),
        },
    }
}

fn from_json(value: &Value) -> Entry {
    let kind = value["kind"].as_str().unwrap_or_default();
    match kind {
        "element" => Entry::Element {
            tag: value["tag"]
                .as_str()
                .unwrap_or_default()
                .to_ascii_lowercase(),
            attrs: value["attrs"]
                .as_array()
                .map(|items| {
                    let mut attrs: Vec<(String, String)> = items
                        .iter()
                        .map(|pair| {
                            normalise_attr(
                                pair[0].as_str().unwrap_or_default(),
                                pair[1].as_str().unwrap_or_default(),
                            )
                        })
                        .collect();
                    attrs.sort();
                    attrs
                })
                .unwrap_or_default(),
            text: value["text"].as_str().unwrap_or_default().to_owned(),
            path: value["path"].as_str().unwrap_or_default().to_owned(),
        },
        "text" => Entry::Text {
            role: if value["role"].as_str() == Some("tail") {
                "tail"
            } else {
                "text"
            },
            value: value["value"].as_str().unwrap_or_default().to_owned(),
            owner_tag: value["owner_tag"]
                .as_str()
                .unwrap_or_default()
                .to_ascii_lowercase(),
        },
        "attr" => Entry::Attr {
            name: value["name"].as_str().unwrap_or_default().to_owned(),
            value: value["value"].as_str().unwrap_or_default().to_owned(),
            owner_tag: value["owner_tag"]
                .as_str()
                .unwrap_or_default()
                .to_ascii_lowercase(),
        },
        other => panic!("unknown result kind {other:?} in the corpus"),
    }
}

