// the test
// ---------------------------------------------------------------------------

/// Compare one row; `Ok(())` when the port reproduces Python exactly.
fn check_row(doc: &Document, row: &Value, shape_stable: bool) -> Result<(), String> {
    let selector = row["selector"].as_str().unwrap_or_default();

    // Rows carrying a `context` were evaluated in Python from that element
    // instead of from the document: `Selector(html).css(ctx)[0].css(sel)`.
    let root = match row.get("context").and_then(Value::as_str) {
        None => doc.root(),
        Some(context) => *parse_selector(context)
            .map_err(|e| format!("context {context:?} does not parse: {e}"))?
            .select_elements(doc.root())
            .first()
            .ok_or_else(|| format!("context {context:?} selects nothing here"))?,
    };

    if let Some(expected_error) = row.get("error").and_then(Value::as_str) {
        return match parse_selector(selector) {
            Err(_) => Ok(()),
            Ok(_) => Err(format!(
                "python rejected the selector ({expected_error}) but we parsed it"
            )),
        };
    }

    let group = parse_selector(selector).map_err(|e| format!("we failed to parse: {e}"))?;
    let ours: Vec<Entry> = group
        .select(root)
        .iter()
        .map(from_match)
        .filter(|e| !e.is_blank_text())
        .collect();
    let theirs: Vec<Entry> = row["results"]
        .as_array()
        .map(|items| items.iter().map(from_json).collect::<Vec<_>>())
        .unwrap_or_default()
        .into_iter()
        .filter(|e| !e.is_blank_text())
        .collect();

    let ours_keys: Vec<String> = ours.iter().map(Entry::key).collect();
    let theirs_keys: Vec<String> = theirs.iter().map(Entry::key).collect();
    if ours_keys != theirs_keys {
        let missing: Vec<&String> = theirs_keys
            .iter()
            .filter(|k| !ours_keys.contains(k))
            .collect();
        let extra: Vec<&String> = ours_keys
            .iter()
            .filter(|k| !theirs_keys.contains(k))
            .collect();
        return Err(format!(
            "node sets differ ({} ours vs {} python)\n      missing: {:?}\n      extra:   {:?}",
            ours_keys.len(),
            theirs_keys.len(),
            &missing[..missing.len().min(4)],
            &extra[..extra.len().min(4)],
        ));
    }

    if shape_stable {
        let ours_paths: Vec<Option<&str>> = ours.iter().map(Entry::path).collect();
        let theirs_paths: Vec<Option<&str>> = theirs.iter().map(Entry::path).collect();
        if ours_paths != theirs_paths {
            return Err(format!(
                "same nodes, different document positions: ours {ours_paths:?} vs python {theirs_paths:?}"
            ));
        }
    }

    Ok(())
}

#[test]
fn css_selection_matches_the_reference_implementation() {
    let docs: Vec<(&str, Document)> = PAGES
        .iter()
        .map(|(name, html)| (*name, Document::parse_with(html, &ParseOptions::new())))
        .collect();

    let expected: BTreeSet<(&str, &str, &str)> = EXPECTED_DIVERGENCES
        .iter()
        .map(|(page, context, selector, _)| (*page, *context, *selector))
        .collect();
    let expected_everywhere: BTreeSet<&str> = EXPECTED_DIVERGENT_SELECTORS
        .iter()
        .map(|(selector, _)| *selector)
        .collect();

    let mut total = 0usize;
    let mut passed = 0usize;
    let mut unexpected: Vec<String> = Vec::new();
    let mut stale: Vec<(String, String, String)> = Vec::new();

    for line in CORPUS.lines().filter(|l| !l.trim().is_empty()) {
        let row: Value = serde_json::from_str(line).expect("corpus row is valid JSON");
        let page = row["page"].as_str().expect("row has a page");
        let selector = row["selector"].as_str().expect("row has a selector");
        let shape_stable = row["shape_stable"].as_bool().unwrap_or(false);
        let context = row.get("context").and_then(Value::as_str).unwrap_or("");
        let (_, doc) = docs
            .iter()
            .find(|(name, _)| *name == page)
            .unwrap_or_else(|| panic!("corpus names an unknown page {page:?}"));

        total += 1;
        let known =
            expected.contains(&(page, context, selector)) || expected_everywhere.contains(selector);
        match check_row(doc, &row, shape_stable) {
            Ok(()) => {
                passed += 1;
                if known {
                    stale.push((page.to_owned(), context.to_owned(), selector.to_owned()));
                }
            }
            Err(why) => {
                if !known {
                    unexpected.push(format!(
                        "  [{page}]{}{selector}\n      {why}",
                        if context.is_empty() {
                            " ".to_owned()
                        } else {
                            format!(" (from {context}) ")
                        }
                    ));
                }
            }
        }
    }

    let report = format!(
        "{passed}/{total} rows reproduce the reference implementation \
         ({} declared divergences + {} selector-wide)",
        EXPECTED_DIVERGENCES.len(),
        EXPECTED_DIVERGENT_SELECTORS.len()
    );
    assert!(
        stale.is_empty(),
        "{report}\nEXPECTED_DIVERGENCES is stale — these rows now pass and must be removed: {stale:#?}"
    );
    assert!(
        unexpected.is_empty(),
        "{report}\n{} undeclared mismatches:\n{}",
        unexpected.len(),
        unexpected.join("\n")
    );
    println!("{report}");
}
